import{_ as t,a as s,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"MCP Server","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"register-claude-code","title":"Register — Claude Code","description":"Run from inside the cloned repo so $(pwd) fills the absolute path. Verify shows the server connected.","request":"cd /path/to/mcp\\nnpm install\\n\\nclaude mcp add bagisto-mcp -- node \\"$(pwd)/src/index.mjs\\"\\n","response":"$ claude mcp list\\nbagisto-mcp   node …/src/index.mjs   ✓ Connected\\n"},{"id":"register-codex","title":"Register — Codex CLI","description":"Codex reads MCP servers from ~/.codex/config.toml. Recent builds can also add it from the CLI (run inside the cloned repo).","request":"cd /path/to/mcp\\nnpm install\\n\\ncodex mcp add bagisto-mcp -- node \\"$(pwd)/src/index.mjs\\"\\n","response":"# ~/.codex/config.toml (equivalent)\\n[mcp_servers.bagisto-mcp]\\ncommand = \\"node\\"\\nargs = [\\"<ABSOLUTE_PATH_TO_REPO>/src/index.mjs\\"]\\n\\n$ codex mcp list\\nbagisto-mcp\\n"},{"id":"register-antigravity","title":"Register — Antigravity","description":"Antigravity reads a JSON MCP config. Add a stdio server pointing node at the absolute path to src/index.mjs.","request":"{\\n  \\"mcpServers\\": {\\n    \\"bagisto-mcp\\": {\\n      \\"command\\": \\"node\\",\\n      \\"args\\": [\\"<ABSOLUTE_PATH_TO_REPO>/src/index.mjs\\"]\\n    }\\n  }\\n}\\n","response":"Server \\"bagisto-mcp\\" appears in the MCP panel with 4 tools:\\nsearch_api_docs, list_endpoints, get_doc, refresh_api_docs\\n"}]},"headers":[],"relativePath":"api/build-with-ai/mcp-server.md","filePath":"api/build-with-ai/mcp-server.md","lastUpdated":1787290888000}'),n={name:"api/build-with-ai/mcp-server.md"};function i(r,e,d,l,c,h){return o(),s("div",null,e[0]||(e[0]=[a(`<h1 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h1><p>An <strong>optional</strong> <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> server that lets an AI agent search this documentation on demand, from inside the editor, while it writes code. It <strong>runs locally</strong> — nothing to host — and by default indexes the latest published docs, so the agent reads the same reference you do.</p><p>It is optional: <a href="/llms.txt"><code>/llms.txt</code></a> and <a href="/llms-full.txt"><code>/llms-full.txt</code></a> cover the same knowledge statically. Add the MCP server when you want the agent to pull the <em>exact</em> current page for an endpoint mid-task instead of ingesting the whole index.</p><h2 id="why-use-it" tabindex="-1">Why use it <a class="header-anchor" href="#why-use-it" aria-label="Permalink to &quot;Why use it&quot;">​</a></h2><ul><li><strong>Live lookup while coding.</strong> The agent fetches the precise request/response shape for an endpoint the moment it needs it — no copy-pasting docs into the chat.</li><li><strong>Always current.</strong> It indexes the published docs, not a stale snapshot from training data.</li><li><strong>Smaller context.</strong> The agent pulls only the page it is working on, leaving room for your code.</li></ul><h2 id="tools-it-exposes" tabindex="-1">Tools it exposes <a class="header-anchor" href="#tools-it-exposes" aria-label="Permalink to &quot;Tools it exposes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>search_api_docs</code></td><td>Ranked full-text search across the API documentation</td></tr><tr><td><code>list_endpoints</code></td><td>Enumerate endpoints, filterable by transport (<code>rest</code>/<code>graphql</code>) and menu</td></tr><tr><td><code>get_doc</code></td><td>Fetch one page&#39;s full content by path</td></tr><tr><td><code>refresh_api_docs</code></td><td>Re-pull the latest docs in-session, no restart</td></tr></tbody></table><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/bagisto/mcp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Requires <strong>Node 18+</strong>. Then register it with your agent — the panel on the right has the exact command for <strong>Claude Code</strong>, <strong>Codex</strong>, and <strong>Antigravity</strong>. Any other MCP client (Cursor, Windsurf, VS Code) uses the same stdio <code>node &lt;path&gt;/src/index.mjs</code> form.</p><ul><li><strong>Repository:</strong> <a href="https://github.com/bagisto/mcp" target="_blank" rel="noreferrer"><code>bagisto/mcp</code></a></li></ul><h2 id="docs-source" tabindex="-1">Docs source <a class="header-anchor" href="#docs-source" aria-label="Permalink to &quot;Docs source&quot;">​</a></h2><p>By default the server fetches <code>https://api-docs.bagisto.com/llms-full.txt</code> and caches it locally. To pin a local snapshot or point at a mirror, set <code>BAGISTO_DOCS_LLMS</code> to a URL or file path when registering. Call <code>refresh_api_docs</code> to pull newly-published docs mid-session.</p><h2 id="do-you-need-it" tabindex="-1">Do you need it? <a class="header-anchor" href="#do-you-need-it" aria-label="Permalink to &quot;Do you need it?&quot;">​</a></h2><p>No — it is a convenience, not a requirement. With the <a href="/api/build-with-ai/agent-skills.html">Agent Skills</a> installed and <a href="/llms.txt"><code>/llms.txt</code></a> reachable, you already have everything needed to build. Add the MCP server for on-demand, in-editor doc search on top of that.</p>`,15)]))}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
